          automatics: [ { name: "5-Speed Automatic (ZF 5HP24)", torqueLimit: "420 Nm", oilType: "ZF Lifeguard 5", note: "The standard transmission for the late 840Ci. A smooth, refined 5-speed. However, the 'A-drum' is a globally known failure point; if it tears, the car loses forward gears. Strict fluid maintenance is required." } ]
