        engineeringData: { blockDesign: "90-degree V8, All-Aluminum Block. The M62 is an evolution of the M60. It utilizes highly robust Alusil cylinder liners, completely resolving the catastrophic Nikasil degradation issues of the early 90s. The block is exceptionally rigid and runs incredibly smoothly.", crankshaft: "Forged Steel, supported by 5 massive main bearings. Features a cross-plane design for the classic, thunderous V8 rumble.", pistonSpeed: "14.6 m/s @ 6000 RPM.", alternator: "140A Bosch (Air cooled) or 150A Water-cooled on very late models. Highly reliable standard design.", rotatingAssembly: { pistonConstruction: "Cast aluminum alloy. Features a 10.0:1 compression ratio.", wristPinDiameter: "22 mm.", connectingRodLength: "143 mm.", rodBoltSize: "M10.", crankMainJournal: "70.0 mm.", crankRodJournal: "54.0 mm.", rodRatio: "1.60." }, cylinderHead: { combustionChamberVol: "Pent-roof combustion chamber.", intakePortFlow: "32-valve DOHC design. The cylinder heads flow incredibly well, featuring dual overhead camshafts driven by a single-row timing chain (unlike the M60's double row).", valveSizes: "Intake: 35.0 mm / Exhaust: 30.5 mm.", valveStemDiameter: "6.0 mm.", camshaftDuration: "Fixed duration. The early M62B44 in the E31 does not feature VANOS variable valve timing, making it mechanically simpler and highly reliable compared to the later M62TU.", lifterType: "Hydraulic bucket tappets.", specialFeature: "Alusil Block & 4.4L Displacement. BMW bumped the displacement from 4.0L to 4.4L, resulting in a massive increase in low-end torque. This completely transformed the driving dynamics of the heavy E31, making it a much more relaxed and effortless grand tourer." }, oilAndCooling: { oilSquirters: "Yes, dedicated high-pressure under-piston cooling jets.", oilPumpType: "Gerotor pump driven by a dedicated chain. The oil pump bolt issue of the M60 was largely resolved.", thermostatOpening: "105°C Electronically mapped thermostat (Runs incredibly hot to pass emissions, rapidly destroying all rubber gaskets).", oilCooler: "Integrated heat exchanger." }, fuelSystem: { systemType: "Bosch Motronic M5.2 Multi-Point Port Injection.", maxPressure: "3.5 Bar (Fuel Rail).", injectors: "8x Bosch Solenoid Injectors. Highly reliable and completely immune to carbon buildup." }, tuningLimits: { maxSafeTorqueStock: "600 Nm (The internals are forged/overbuilt).", maxSafePowerStock: "450 hp (The M62 handles supercharging exceptionally well).", maxSafeRPM: "6500 RPM", weakestLink: "Timing Chain Guides (Fatal), Valley Pan Gasket, OSV Plate, Intake Manifold Gaskets." }, electrical: { coils: "Individual Coil Pack system (8x Coil-on-Plug).", ecu: "Bosch Motronic M5.2." } },
        recommendedParts: { description: "Crucial maintenance parts to prevent the fatal timing chain guide shattering and massive vacuum leaks of the M62 V8.", parts: [ { category: "Timing Chain Guide Kit", brand: "Genuine BMW / INA", note: "CRITICAL: Must be replaced before 150k km to prevent catastrophic engine death." }, { category: "Valley Pan Cover & Gasket", brand: "Genuine BMW / Uro", note: "CRITICAL: Replaces the leaking coolant seal under the intake manifold." }, { category: "PCV / OSV Plate", brand: "Genuine BMW / Febi", note: "CRITICAL: Cures massive vacuum leaks, rough idle, and extreme oil consumption." }, { category: "Intake Manifold Gasket Set", brand: "Elring / Victor Reinz", note: "Cures rough idle. Must be replaced when doing the OSV or Valley Pan." }, { category: "Valve Cover Gasket Set", brand: "Victor Reinz", note: "Cures oil leaks onto the hot exhaust. Ensure magnesium covers are not warped." }, { category: "Water Pump & Thermostat", brand: "Saleri / Wahler", note: "Proactively maintain the cooling system to protect the aluminum block." }, { category: "Timing Chain Tensioner", brand: "INA", note: "Replace the primary tensioner externally to prologue chain guide life." }, { category: "Hydraulic Brake Accumulator", brand: "Febi Bilstein", note: "CRITICAL: The 'Brake Bomb' must be replaced to restore brake assist." } ] },
