            { interval: "120,000 km", timeLimit: "10 years", task: "Radiator & Expansion Tank", details: "The plastic end tanks on the original radiator and expansion tank will explode without warning due to the 105C operating temp.", parts: ["Behr Radiator", "Expansion Tank"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "350 EUR" }
