        engineeringData: { blockDesign: "60-degree V12, All-Aluminum Block with Alusil cylinder liners. The M70 was BMW's first production V12 engine. It is essentially two legendary M20 inline-6 engines joined at the crankshaft. The block is phenomenally strong and completely immune to the Nikasil degradation issues that plagued the V8s.", crankshaft: "Forged Steel, supported by 7 massive main bearings. It provides the legendary, perfectly balanced, vibration-free V12 idle. A coin can literally balance on the intake manifold while running.", pistonSpeed: "13.8 m/s @ 6000 RPM.", alternator: "140A Bosch (Air cooled).", rotatingAssembly: { pistonConstruction: "Cast aluminum alloy. Features a low 8.8:1 compression ratio, allowing the engine to run on incredibly poor fuel qualities globally.", wristPinDiameter: "22 mm.", connectingRodLength: "135 mm.", rodBoltSize: "M10.", crankMainJournal: "60.0 mm.", crankRodJournal: "45.0 mm.", rodRatio: "1.60." }, cylinderHead: { combustionChamberVol: "Wedge-shaped combustion chamber.", intakePortFlow: "24-valve SOHC design (2 valves per cylinder). The M70 does not prioritize high RPM airflow; it is designed entirely for massive low-end torque and absolute silence. The SOHC valvetrain relies on eccentric rockers and a hollow oil spray bar.", valveSizes: "Intake: 42.0 mm / Exhaust: 36.0 mm.", valveStemDiameter: "7.0 mm.", camshaftDuration: "Fixed duration. Mechanically very simple and highly reliable.", lifterType: "Hydraulic bucket tappets.", specialFeature: "Dual Engine Management & Electronic Throttles. The M70 is a technological pioneer. It was one of the first production cars to use drive-by-wire electronic throttle bodies (DK motors). However, the engine is managed as two entirely separate inline-6s, making diagnostics a nightmare. If Bank 1 loses a fuel pump, Bank 2 will continue running the car, dragging the dead cylinders along." }, oilAndCooling: { oilSquirters: "Yes, dedicated high-pressure under-piston cooling jets.", oilPumpType: "Gerotor pump driven by a dedicated chain.", thermostatOpening: "85°C Mechanical thermostat (Runs cool, preserving gaskets longer).", oilCooler: "Features an external air-to-oil heat exchanger." }, fuelSystem: { systemType: "Dual Bosch Motronic M1.7 Multi-Point Port Injection.", maxPressure: "3.0 Bar (Fuel Rail). Driven by TWO separate in-tank fuel pumps.", injectors: "12x Bosch Solenoid Injectors. Highly reliable." }, tuningLimits: { maxSafeTorqueStock: "650 Nm (The internals are forged/overbuilt).", maxSafePowerStock: "500 hp (The M70 handles twin-turbocharging exceptionally well, as proven by the Alpina B12).", maxSafeRPM: "6000 RPM", weakestLink: "Camshaft Oil Spray Bar Bolts (Fatal), DK Throttle Bodies (Limp Mode), Intake Manifold Gaskets (Vacuum Leaks), Dual Fuel Pumps, Ignition Distributors." }, electrical: { coils: "Dual Ignition Coil system feeding two distributors.", ecu: "Dual Bosch Motronic M1.7 + EML Module (Requires physical EPROM chip replacement for tuning)." } },
        recommendedParts: { description: "Crucial maintenance parts to prevent the fatal oil starvation and terrifying EML limp mode failures of the classic M70 V12.", parts: [ { category: "Camshaft Oil Spray Bar Bolts", brand: "Genuine BMW", note: "CRITICAL: Must be safety-wired immediately to save the valvetrain." }, { category: "DK Throttle Body Rebuild", brand: "Specialist Service", note: "CRITICAL: Permanently cures the infamous V12 EML limp mode." }, { category: "Intake Manifold Gasket Set", brand: "Elring / Victor Reinz", note: "CRITICAL: Cures massive vacuum leaks and surging idle. Requires multiple complex gaskets." }, { category: "Valve Cover Gasket Set", brand: "Victor Reinz", note: "Cures oil leaks onto the hot exhaust. Must do when safety-wiring the spray bar." }, { category: "Distributor Caps & Rotors", brand: "Bosch", note: "CRITICAL: Requires 2 sets. Fixes severe misfires on the V12." }, { category: "Ignition Wire Set", brand: "Bremi / Bosch", note: "Requires a massive 12-wire harness. Expensive but mandatory for smooth running." }, { category: "Fuel Pumps", brand: "Bosch / Pierburg", note: "Requires 2 units. Proactively replace 30-year-old pumps to prevent one bank dying." }, { category: "Hydraulic Brake Accumulator", brand: "Febi Bilstein", note: "CRITICAL: The 'Brake Bomb' must be replaced to restore brake assist." } ] },
