            { interval: "60,000 km", timeLimit: "5 years", task: "Ignition System Overhaul", details: "CRITICAL: Replace the 12 spark plugs, the TWO distributor caps, and TWO rotors. The M70 is highly sensitive to weak ignition, causing severe misfires.", parts: ["12x Plugs", "2x Dist. Caps/Rotors"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "400 EUR" },
            { interval: "150,000 km", timeLimit: "Unlimited", task: "Dual Fuel Pump Replacement", details: "Proactively replace both in-tank fuel pumps. If one dies, you will be driving a 2-ton car on an inline-6 dragging 6 dead cylinders.", parts: ["2x Bosch Fuel Pumps"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "450 EUR" }
