            { interval: "150,000 km", timeLimit: "Unlimited", task: "Engine & Transmission Mounts", details: "Replace the sagging rubber mounts to restore the legendary, coin-balancing V12 idle feel.", parts: ["Lemförder Mounts"], importance: "Medium", laborDifficulty: "Intermediate", estimatedCost: "250 EUR" }
