        engineeringData: { blockDesign: "60-degree V12, All-Aluminum Block with Alusil cylinder liners. The M73 is an evolutionary upgrade to the M70. The displacement was increased from 5.0L to 5.4L, resulting in a substantial bump in low-end torque. The block remains phenomenally strong and immune to cylinder degradation issues.", crankshaft: "Forged Steel, supported by 7 massive main bearings. It provides the legendary, perfectly balanced, vibration-free V12 idle.", pistonSpeed: "13.8 m/s @ 6000 RPM.", alternator: "140A Bosch (Air cooled).", rotatingAssembly: { pistonConstruction: "Cast aluminum alloy. Features an increased 10.0:1 compression ratio (up from 8.8:1 in the M70) for better efficiency and torque.", wristPinDiameter: "22 mm.", connectingRodLength: "135 mm.", rodBoltSize: "M10.", crankMainJournal: "60.0 mm.", crankRodJournal: "45.0 mm.", rodRatio: "1.60." }, cylinderHead: { combustionChamberVol: "Wedge-shaped combustion chamber.", intakePortFlow: "24-valve SOHC design (2 valves per cylinder). The SOHC valvetrain relies on eccentric rockers. BMW updated the camshafts to utilize roller rockers in the M73, drastically reducing friction and eliminating the fatal oil spray bar bolt backing-out issue that plagued the M70.", valveSizes: "Intake: 42.0 mm / Exhaust: 36.0 mm.", valveStemDiameter: "7.0 mm.", camshaftDuration: "Fixed duration. Mechanically very simple and highly reliable.", lifterType: "Hydraulic bucket tappets.", specialFeature: "Roller Rockers & Hot-Film MAF. The switch to roller rockers saved the valvetrain from self-destruction, and the switch to modern Hot-Film Mass Air Flow sensors made the dual-ECU system vastly more reliable and easier to diagnose than the old mechanical flap-style sensors." }, oilAndCooling: { oilSquirters: "Yes, dedicated high-pressure under-piston cooling jets.", oilPumpType: "Gerotor pump driven by a dedicated chain.", thermostatOpening: "95°C Mechanical thermostat (Runs hotter than M70 for emissions, degrading gaskets faster).", oilCooler: "Features an external air-to-oil heat exchanger." }, fuelSystem: { systemType: "Dual Bosch Motronic M5.2 Multi-Point Port Injection.", maxPressure: "3.0 Bar (Fuel Rail). Driven by TWO separate in-tank fuel pumps.", injectors: "12x Bosch Solenoid Injectors. Highly reliable." }, tuningLimits: { maxSafeTorqueStock: "650 Nm (The internals are forged/overbuilt).", maxSafePowerStock: "500 hp (The M73 handles twin-turbocharging exceptionally well).", maxSafeRPM: "6000 RPM", weakestLink: "Intake Manifold Gaskets (Vacuum Leaks), Dual Fuel Pumps, Ignition Distributors, Valve Cover Gaskets." }, electrical: { coils: "Dual Ignition Coil system feeding two distributors.", ecu: "Dual Bosch Motronic M5.2 (Requires physical EPROM chip replacement for tuning)." } },
        recommendedParts: { description: "Crucial maintenance parts to prevent massive oil leaks and terrifying vacuum leaks on the M73 V12.", parts: [ { category: "Intake Manifold Gasket Set", brand: "Elring / Victor Reinz", note: "CRITICAL: Cures massive vacuum leaks and surging idle. Requires multiple complex gaskets." }, { category: "Valve Cover Gasket Set", brand: "Victor Reinz", note: "CRITICAL: Cures oil leaks onto the hot exhaust (Fire Risk)." }, { category: "Distributor Caps & Rotors", brand: "Bosch", note: "CRITICAL: Requires 2 sets. Fixes severe misfires on the V12." }, { category: "Ignition Wire Set", brand: "Bremi / Bosch", note: "Requires a massive 12-wire harness. Expensive but mandatory for smooth running." }, { category: "Water Pump & Thermostat", brand: "Saleri / Wahler", note: "Replace proactively to ensure bulletproof cooling for the massive V12." }, { category: "PCV Valves", brand: "Genuine BMW", note: "Requires 2 units. Stops oil consumption and blue smoke." }, { category: "Fuel Pumps", brand: "Bosch / Pierburg", note: "Requires 2 units. Proactively replace 30-year-old pumps to prevent one bank dying." }, { category: "Hydraulic Brake Accumulator", brand: "Febi Bilstein", note: "CRITICAL: The 'Brake Bomb' must be replaced to restore brake assist." } ] },
