            { interval: "5 Years", timeLimit: "5 years", task: "Dual Battery Replacement", details: "The E31 8 Series utilizes TWO large batteries in the trunk. Both must be replaced simultaneously to prevent massive electrical and EML module gremlins.", parts: ["2x 95Ah Batteries"], importance: "High", laborDifficulty: "Easy", estimatedCost: "350 EUR" }
