        engineeringData: { blockDesign: "60-degree V12, All-Aluminum Block with Alusil cylinder liners. The S70 is a true M-Power engine block (the same architecture that would later evolve into the legendary McLaren F1 engine). BMW M increased the displacement from 5.0L to 5.6L, fitted a forged crankshaft, and heavily upgraded the internals for aggressive, high-RPM response.", crankshaft: "Forged Steel, supported by 7 massive main bearings. It provides the legendary, perfectly balanced, vibration-free V12 idle while handling the immense 550Nm torque.", pistonSpeed: "15.0 m/s @ 6400 RPM.", alternator: "140A Bosch (Air cooled).", rotatingAssembly: { pistonConstruction: "Lightweight Cast aluminum alloy. Features a 9.8:1 compression ratio (up from the M70's 8.8:1) for much sharper throttle response and power.", wristPinDiameter: "22 mm.", connectingRodLength: "135 mm.", rodBoltSize: "M10.", crankMainJournal: "60.0 mm.", crankRodJournal: "45.0 mm.", rodRatio: "1.60." }, cylinderHead: { combustionChamberVol: "Wedge-shaped combustion chamber.", intakePortFlow: "24-valve SOHC design. The M Division heavily ported and polished the cylinder heads and installed far more aggressive camshafts to allow the 5.6L engine to breathe at high RPMs.", valveSizes: "Intake: 42.0 mm / Exhaust: 36.0 mm.", valveStemDiameter: "7.0 mm.", camshaftDuration: "M-Specific Aggressive Profile. Driven by the immortal single-row timing chain.", lifterType: "Hydraulic bucket tappets.", specialFeature: "M-Power Architecture & AHK. The S70 completely transforms the 8-Series. The true marvel of the CSi is the AHK (Active Rear-Axle Kinematics), a highly complex hydraulic computer system that actively steers the rear wheels, making the massive 2-ton car feel incredibly agile." }, oilAndCooling: { oilSquirters: "Yes, dedicated high-pressure under-piston cooling jets.", oilPumpType: "Gerotor pump driven by a dedicated chain.", thermostatOpening: "85°C Mechanical thermostat.", oilCooler: "Features an uprated external air-to-oil heat exchanger." }, fuelSystem: { systemType: "Dual Bosch Motronic M1.7 Multi-Point Port Injection.", maxPressure: "3.0 Bar (Fuel Rail). Driven by TWO separate in-tank fuel pumps.", injectors: "12x Bosch Solenoid Injectors. Highly reliable." }, tuningLimits: { maxSafeTorqueStock: "700 Nm (The Getrag 560G handles power effortlessly).", maxSafePowerStock: "500 hp (The S70 block is incredibly strong, but tuning it ruins its extreme classic value).", maxSafeRPM: "6500 RPM", weakestLink: "Camshaft Oil Spray Bar Bolts (Fatal), DK Throttle Bodies (Limp Mode), Intake Manifold Gaskets (Vacuum Leaks), Dual Fuel Pumps, AHK System." }, electrical: { coils: "Dual Ignition Coil system feeding two distributors.", ecu: "Dual Bosch Motronic M1.7 + M-Specific EML Module (Requires physical EPROM chip replacement for tuning)." } },
        recommendedParts: { description: "Crucial maintenance parts to prevent the fatal oil starvation and terrifying EML limp mode failures of the incredibly rare S70 V12.", parts: [ { category: "Camshaft Oil Spray Bar Bolts", brand: "Genuine BMW", note: "CRITICAL: Must be safety-wired immediately to save the valvetrain." }, { category: "DK Throttle Body Rebuild", brand: "Specialist Service", note: "CRITICAL: Permanently cures the infamous V12 EML limp mode." }, { category: "Intake Manifold Gasket Set", brand: "Elring / Victor Reinz", note: "CRITICAL: Cures massive vacuum leaks and surging idle. Requires multiple complex gaskets." }, { category: "Valve Cover Gasket Set", brand: "Victor Reinz", note: "Cures oil leaks onto the hot exhaust. Must do when safety-wiring the spray bar." }, { category: "Distributor Caps & Rotors", brand: "Bosch", note: "CRITICAL: Requires 2 sets. Fixes severe misfires on the V12." }, { category: "Ignition Wire Set", brand: "Bremi / Bosch", note: "Requires a massive 12-wire harness. Expensive but mandatory for smooth running." }, { category: "Fuel Pumps", brand: "Bosch / Pierburg", note: "Requires 2 units. Proactively replace 30-year-old pumps to prevent one bank dying." }, { category: "AHK Hydraulic Accumulator", brand: "Genuine BMW", note: "CRITICAL: The specific pressure sphere for the rear steering system." } ] },
