        sisterModels: [ { name: "McLaren F1 (S70/2)", note: "The legendary McLaren F1 utilized the S70/2 engine, which was heavily based on the architecture of the 850CSi's S70B56, making this block one of the most historically significant engines BMW ever produced." } ],
        tuningPotential: [
          { stage: "Stage 1 (Wokke Performance Chips)", power: "400 - 415 hp", notes: "The ultimate value upgrade for the incredible S70. It requires opening the TWO Bosch Motronic ECUs and the EML module, and physically replacing the factory EPROM chips with custom-tuned chips. It completely removes the sluggish factory drive-by-wire programming, makes throttle response incredibly aggressive, removes the top speed limiter, and unlocks hidden M-Power horsepower. It completely wakes the V12 up.", zeroToHundred: "5.5s", hundredToTwoHundred: "N/A" },
          { stage: "Stage 2 (Full Exhaust & Intakes)", power: "420 - 440 hp", notes: "Requires custom exhaust work, removing the highly restrictive factory catalytic converters and massive resonators. This provides an absolutely legendary, aggressive M-V12 howl that is deeply intoxicating.", zeroToHundred: "5.3s", hundredToTwoHundred: "N/A" },
          { stage: "Stage 3 (Not Recommended)", power: "N/A", notes: "The 850CSi is an incredibly rare, historically significant, bona fide classic M-Car. Heavily modifying the S70 engine with superchargers or standalone ECUs will completely ruin its massive collector value. Preserve it, protect it, and leave it naturally aspirated.", zeroToHundred: "N/A", hundredToTwoHundred: "N/A" }
        ],
