        engineeringData: { blockDesign: "60-degree V12, All-Aluminum Block with Alusil cylinder liners. Alpina took the phenomenal M70 block and installed lightweight, higher-compression Mahle pistons. The block is phenomenally strong and completely immune to the Nikasil degradation issues.", crankshaft: "Forged Steel, supported by 7 massive main bearings. It provides the legendary, perfectly balanced, vibration-free V12 idle. A coin can literally balance on the intake manifold while running.", pistonSpeed: "13.8 m/s @ 6000 RPM.", alternator: "140A Bosch (Air cooled).", rotatingAssembly: { pistonConstruction: "Lightweight Forged Mahle aluminum alloy. Features a higher 9.5:1 compression ratio (up from the M70's 8.8:1) for much sharper throttle response and power.", wristPinDiameter: "22 mm.", connectingRodLength: "135 mm.", rodBoltSize: "M10.", crankMainJournal: "60.0 mm.", crankRodJournal: "45.0 mm.", rodRatio: "1.60." }, cylinderHead: { combustionChamberVol: "Wedge-shaped combustion chamber.", intakePortFlow: "24-valve SOHC design. Alpina heavily ported and polished the intake tracts and installed far more aggressive, higher-lift camshafts to allow the 5.0L engine to breathe significantly better at high RPMs.", valveSizes: "Intake: 42.0 mm / Exhaust: 36.0 mm.", valveStemDiameter: "7.0 mm.", camshaftDuration: "Alpina-Specific Aggressive Profile. Driven by the immortal single-row timing chain.", lifterType: "Hydraulic bucket tappets.", specialFeature: "Alpina Calibration & Electronic Throttles. The engine is managed as two entirely separate inline-6s, making diagnostics a nightmare. Alpina heavily reprogrammed the dual ECUs and the EML module to provide a far more aggressive, responsive throttle map compared to the sluggish standard 850i." }, oilAndCooling: { oilSquirters: "Yes, dedicated high-pressure under-piston cooling jets.", oilPumpType: "Gerotor pump driven by a dedicated chain.", thermostatOpening: "85°C Mechanical thermostat (Runs cool, preserving gaskets longer).", oilCooler: "Features an external air-to-oil heat exchanger." }, fuelSystem: { systemType: "Dual Bosch Motronic M1.7 Multi-Point Port Injection.", maxPressure: "3.0 Bar (Fuel Rail). Driven by TWO separate in-tank fuel pumps.", injectors: "12x Bosch Solenoid Injectors. Highly reliable." }, tuningLimits: { maxSafeTorqueStock: "650 Nm (The internals are forged/overbuilt).", maxSafePowerStock: "500 hp (The block is incredibly strong, but tuning an incredibly rare Alpina ruins its massive classic value).", maxSafeRPM: "6000 RPM", weakestLink: "Camshaft Oil Spray Bar Bolts (Fatal), DK Throttle Bodies (Limp Mode), Intake Manifold Gaskets (Vacuum Leaks), Dual Fuel Pumps, Ignition Distributors." }, electrical: { coils: "Dual Ignition Coil system feeding two distributors.", ecu: "Dual Bosch Motronic M1.7 + Alpina EML Module." } },
        recommendedParts: { description: "Crucial maintenance parts to prevent the fatal oil starvation and terrifying EML limp mode failures of the classic Alpina V12.", parts: [ { category: "Camshaft Oil Spray Bar Bolts", brand: "Genuine BMW", note: "CRITICAL: Must be safety-wired immediately to save the valvetrain." }, { category: "DK Throttle Body Rebuild", brand: "Specialist Service", note: "CRITICAL: Permanently cures the infamous V12 EML limp mode." }, { category: "Intake Manifold Gasket Set", brand: "Elring / Victor Reinz", note: "CRITICAL: Cures massive vacuum leaks and surging idle. Requires multiple complex gaskets." }, { category: "Valve Cover Gasket Set", brand: "Victor Reinz", note: "Cures oil leaks onto the hot exhaust. Must do when safety-wiring the spray bar." }, { category: "Distributor Caps & Rotors", brand: "Bosch", note: "CRITICAL: Requires 2 sets. Fixes severe misfires on the V12." }, { category: "Ignition Wire Set", brand: "Bremi / Bosch", note: "Requires a massive 12-wire harness. Expensive but mandatory for smooth running." }, { category: "Fuel Pumps", brand: "Bosch / Pierburg", note: "Requires 2 units. Proactively replace 30-year-old pumps to prevent one bank dying." }, { category: "Hydraulic Brake Accumulator", brand: "Febi Bilstein", note: "CRITICAL: The 'Brake Bomb' must be replaced to restore brake assist." } ] },
