            { interval: "40,000 km", timeLimit: "4 years", task: "Fuel Filter Replacement", details: "Replace the TWO inline metal fuel filters to protect the Bosch injectors.", parts: ["2x Mahle Fuel Filters"], importance: "High", laborDifficulty: "Easy", estimatedCost: "60 EUR" }
