        engineeringData: { blockDesign: "Closed-deck Aluminum block with wire-arc sprayed cylinder liners. The B58 'TU' represents the absolute pinnacle of BMW's inline-6 engineering. The closed-deck design provides immense rigidity and durability, allowing it to safely handle incredibly high boost pressures without cylinder wall distortion. The acoustic refinement is exceptionally high, delivering the legendary, perfectly balanced BMW inline-6 smoothness.", crankshaft: "Forged Steel, supported by 7 massive main bearings. Exceptionally smooth, perfectly balanced, and capable of withstanding unbelievable torque loads.", pistonSpeed: "14.4 m/s @ 6500 RPM.", alternator: "48V Starter-Generator. A highly advanced unit that replaces the traditional alternator and starter, providing instant electric boost and allowing the engine to seamlessly shut off while coasting.", rotatingAssembly: { pistonConstruction: "Cast aluminum alloy. Features an 11.0:1 compression ratio, perfectly optimized for incredibly sharp throttle response and maximum fuel efficiency. While cast, the pistons and rods are immensely strong, handling 600+ horsepower before requiring forged upgrades.", wristPinDiameter: "22 mm.", connectingRodLength: "148 mm.", rodBoltSize: "M9.", crankMainJournal: "50.0 mm.", crankRodJournal: "50.0 mm.", rodRatio: "1.56." }, cylinderHead: { combustionChamberVol: "Pent-roof combustion chamber deeply optimized for centralized direct injection.", intakePortFlow: "24-valve DOHC design. The B58 integrates the air-to-water intercooler directly into the intake manifold, vastly reducing the charge air volume and entirely eliminating turbo lag. The TU update integrated the exhaust manifold directly into the head.", valveSizes: "Intake: 32.0 mm / Exhaust: 29.0 mm.", valveStemDiameter: "5.0 mm.", camshaftDuration: "Variable on BOTH Intake and Exhaust sides. Controlled dynamically by Double VANOS (mounted at the rear) and the brilliant Valvetronic lift system.", lifterType: "Hydraulic bucket tappets.", specialFeature: "Rear-Mounted Timing & 48V Mild Hybrid. The TU update brought a split cooling system for targeted thermal management. By moving the timing chain and VANOS actuators to the rear of the engine block, BMW simplified the front accessory drive. The addition of the 48V system further refines the start-stop logic and low-end torque fill." }, oilAndCooling: { oilSquirters: "Yes, dedicated high-pressure under-piston cooling jets.", oilPumpType: "Variable displacement map-controlled pump.", thermostatOpening: "108°C Electronically mapped heat management module for maximum fuel efficiency.", oilCooler: "Features an external air-to-oil cooler." }, fuelSystem: { systemType: "Bosch High Precision Direct Injection.", maxPressure: "350 Bar (Fuel Rail). Operates at immensely high pressures for perfect atomization.", injectors: "6x Bosch Solenoid Injectors. Vastly more reliable than the catastrophic early-generation N54/N63 Piezo direct injection systems." }, tuningLimits: { maxSafeTorqueStock: "550 Nm (The highly refined ZF transmission clutch packs are the limiting factor without a custom xHP flash).", maxSafePowerStock: "500 - 600 hp (The B58 closed-deck block is an absolute monster, safely handling massive turbo upgrades).", maxSafeRPM: "7000 RPM", weakestLink: "PCV Membrane (Tears), Expansion Tank (Leaks), Charge Pipe (Explodes), OPF Filters, 48V Battery." }, electrical: { coils: "Individual Coil Pack system (6x Coil-on-Plug).", ecu: "Bosch MG1 (Heavily Encrypted - Requires FEMTO unlock if post-06/2020)." } },
        recommendedParts: { description: "Crucial maintenance parts to completely prevent the minor external failures of the otherwise immortal B58 engine core.", parts: [ { category: "PCV Diaphragm Kit", brand: "Aftermarket / Ross Racing", note: "CRITICAL: Replaces the torn rubber membrane without requiring a new valve cover." }, { category: "Coolant Expansion Tank & Cap", brand: "Genuine BMW", note: "CRITICAL: Replaces the weeping plastic tank before it loses pressure." }, { category: "Aluminum Charge Pipe", brand: "FTP / VRSF", note: "CRITICAL: Replaces the exploding plastic factory pipe." }, { category: "Intake Manifold Gaskets", brand: "Genuine BMW", note: "Required if removing the manifold to inspect the air-to-water intercooler." }, { category: "Oil Filter Housing Gasket (OFHG)", brand: "Genuine BMW / Elring", note: "Prevents oil from dripping down the front of the engine." }, { category: "Spark Plugs", brand: "NGK SILZKGR8B8S", note: "Specific plugs; MUST be replaced every 40k km for direct injection." }, { category: "Vibration Damper", brand: "Corteco", note: "Replaces the tearing rubber crank pulley before it throws the belt." }, { category: "48V Auxiliary Battery", brand: "Genuine BMW", note: "Replace if hybrid system throws errors or disables coasting." } ] },
