        engineeringData: { blockDesign: "90-degree V8, All-Aluminum Block with wire-arc sprayed cylinder liners. The N63TU3 retained the revolutionary 'Hot-V' layout but heavily refined the thermal management to prevent the catastrophic failures of the original engine. The timing chain guides were redesigned, and the pistons feature an improved crown design to handle the massive 530hp output.", crankshaft: "Forged Steel, supported by 5 massive main bearings. Exceptionally smooth and perfectly balanced.", pistonSpeed: "14.4 m/s @ 6500 RPM.", alternator: "210A Water-Cooled (Liquid Cooled). A highly over-engineered, incredibly expensive unit encased in a coolant jacket.", rotatingAssembly: { pistonConstruction: "Cast aluminum alloy. Features a 10.5:1 compression ratio.", wristPinDiameter: "22 mm.", connectingRodLength: "144.3 mm.", rodBoltSize: "M10.", crankMainJournal: "70.0 mm.", crankRodJournal: "54.0 mm.", rodRatio: "1.62." }, cylinderHead: { combustionChamberVol: "Direct injection bowl-in-piston design.", intakePortFlow: "32-valve DOHC design. The cylinder heads are 'reverse flow' (intake on the outside, exhaust on the inside). They flow incredible amounts of air but suffer from massive carbon buildup on the intake valves.", valveSizes: "Intake: 33.0 mm / Exhaust: 29.0 mm.", valveStemDiameter: "6.0 mm.", camshaftDuration: "Variable on BOTH Intake and Exhaust sides. Controlled dynamically by Dual VANOS and Valvetronic lift.", lifterType: "Hydraulic bucket tappets.", specialFeature: "Twin-Scroll Turbos & Valvetronic. The TU3 update features vastly larger twin-scroll turbos compared to earlier models, pushing output to 530hp. The Valvetronic system eliminates the traditional throttle body, drastically improving efficiency and providing absolutely devastating, instantaneous throttle response." }, oilAndCooling: { oilSquirters: "Yes, dedicated high-pressure under-piston cooling jets.", oilPumpType: "Variable displacement map-controlled pump.", thermostatOpening: "105°C Electronically mapped thermostat (Runs incredibly hot, rapidly destroying the engine's external rubber seals).", oilCooler: "Features a massive external air-to-oil heat exchanger." }, fuelSystem: { systemType: "High Precision Direct Injection. Upgraded to 350 Bar for the TU3.", maxPressure: "350 Bar (Fuel Rail). Driven by TWO highly stressed mechanical HPFPs.", injectors: "8x Bosch Solenoid Injectors. Vastly more reliable than the fatal early Piezo units." }, tuningLimits: { maxSafeTorqueStock: "800+ Nm (The ZF 8HP75 transmission requires an xHP flash to increase clamping force past this point).", maxSafePowerStock: "700+ hp (The block and forged crank are incredibly strong).", maxSafeRPM: "6500 RPM", weakestLink: "Coolant Expansion Tank (Explodes), Valve Stem Seals (Fail/Smoke), HPFP (Fails), Valvetronic Motors, Carbon Buildup." }, electrical: { coils: "Individual Coil Pack system (8x Coil-on-Plug).", ecu: "Dual Bosch MG1 (Heavily encrypted - Requires physical FEMTO bench unlock)." } },
        recommendedParts: { description: "Crucial maintenance parts to prevent the fatal, catastrophically expensive seal, cooling, and fueling failures of the N63TU3 V8.", parts: [ { category: "Aluminum Coolant Expansion Tank", brand: "Aftermarket Billet", note: "CRITICAL: Replaces the fatally flawed plastic factory tank." }, { category: "Viton Valve Stem Seals", brand: "Elring / Victor Reinz", note: "CRITICAL: Must be replaced using specialized tools to cure the embarrassing blue smoke." }, { category: "High Pressure Fuel Pumps (HPFP)", brand: "Genuine BMW / Bosch", note: "CRITICAL: Requires 2 units. Replaces the failing mechanical pumps." }, { category: "Valvetronic Motors", brand: "VDO / Continental", note: "Requires 2 units. Replace if the engine enters limp mode." }, { category: "Valve Cover Gasket Set", brand: "Victor Reinz", note: "CRITICAL: Requires 2 massive kits. Cures oil leaking onto the hot exhaust manifolds." }, { category: "Upgraded Ignition Coils & Plugs", brand: "Eldor / NGK 1-Step Colder", note: "Mandatory for curing misfires, especially if running Bootmod3 tunes." }, { category: "Vibration Damper", brand: "Corteco", note: "Replaces the tearing rubber crank pulley before it throws the belt." }, { category: "Water Pump & Thermostat", brand: "Saleri / Wahler", note: "Replace proactively to ensure bulletproof cooling for the massive V8." } ] },
