        engineeringData: { blockDesign: "Inline-6, Closed-deck Aluminum block with wire-arc sprayed cylinder liners. The B57 represents a massive architectural leap in refinement and rigidity over the older N57. The acoustic refinement is phenomenal, delivering turbine-like smoothness that entirely masks its diesel nature. However, BMW retained the rear-mounted timing chain (against the firewall) to comply with pedestrian safety crash regulations, turning a simple maintenance item into a ruinously expensive engine-out procedure.", crankshaft: "Forged Steel, supported by 7 main bearings. Exceptionally smooth and perfectly balanced, handling the immense 680Nm torque load effortlessly.", pistonSpeed: "14.4 m/s @ 4000 RPM.", alternator: "180A Valeo/Bosch (Multi-rib belt driven).", rotatingAssembly: { pistonConstruction: "Cast aluminum alloy with high-flow gallery cooling. Features a 16.5:1 compression ratio.", wristPinDiameter: "30 mm.", connectingRodLength: "135 mm.", rodBoltSize: "M10.", crankMainJournal: "60.0 mm.", crankRodJournal: "45.0 mm.", rodRatio: "1.53." }, cylinderHead: { combustionChamberVol: "Direct injection bowl-in-piston design.", intakePortFlow: "24-valve DOHC design. The aluminum casting is excellent, completely eliminating thermal cracking. However, the intake tracts clog rapidly with massive amounts of EGR carbon.", valveSizes: "Intake: 27.2 mm / Exhaust: 27.2 mm.", valveStemDiameter: "6.0 mm.", camshaftDuration: "Mild diesel duration. Driven by the rear-mounted timing chain system.", lifterType: "Hydraulic bucket tappets.", specialFeature: "Sequential Twin-Turbocharging & Rear Timing Chain. The engine was designed for absolute efficiency and massive torque, using a small turbo for immediate response and a large turbo for top-end power. This allows the 3.0L to move the massive 8-Series effortlessly. Unfortunately, the rear-mounted timing chain guarantees massive future labor bills." }, oilAndCooling: { oilSquirters: "Yes, dedicated high-pressure under-piston cooling jets.", oilPumpType: "Variable displacement rotor-type pump driven by a dedicated chain.", thermostatOpening: "88°C Mechanical thermostat.", oilCooler: "Features an external water-to-oil heat exchanger." }, fuelSystem: { systemType: "Bosch CP4.2 Common Rail High-Pressure Pump. Universally known for catastrophic internal failure that sends shrapnel through the entire fuel system.", maxPressure: "2500 Bar (Fuel Rail - immensely high pressure).", injectors: "6x Bosch Solenoid Injectors. Incredibly durable, unless fed metal shrapnel from the CP4." }, tuningLimits: { maxSafeTorqueStock: "750+ Nm (The ZF 8HP75 transmission requires an xHP flash to increase clamping force past this point).", maxSafePowerStock: "450 hp (The closed-deck aluminum block handles massive boost safely).", maxSafeRPM: "4800 RPM", weakestLink: "Bosch CP4 Pump (Fatal/Shrapnel), EGR Cooler (Fire Risk), Rear Timing Chain (Snaps/Engine-Out), SCR/AdBlue System, Swirl Flaps." }, electrical: { coils: "N/A (Compression Ignition).", ecu: "Bosch DDE 8 (Highly tunable)." } },
