        engineeringData: { blockDesign: "Inline-6, Closed-deck Aluminum block with wire-arc sprayed cylinder liners. The B57 represents a massive architectural leap in refinement and rigidity over the older N57. The acoustic refinement is phenomenal, delivering turbine-like smoothness that entirely masks its diesel nature. However, BMW retained the rear-mounted timing chain (against the firewall) to comply with pedestrian safety crash regulations.", crankshaft: "Forged Steel, supported by 7 main bearings. Exceptionally smooth and perfectly balanced, handling the immense 700Nm torque load effortlessly.", pistonSpeed: "14.4 m/s @ 4000 RPM.", alternator: "48V Starter-Generator. A highly advanced unit that replaces the traditional alternator and starter, providing instant electric boost and allowing the engine to seamlessly shut off while coasting at highway speeds.", rotatingAssembly: { pistonConstruction: "Cast aluminum alloy with high-flow gallery cooling. Features a 16.5:1 compression ratio.", wristPinDiameter: "30 mm.", connectingRodLength: "135 mm.", rodBoltSize: "M10.", crankMainJournal: "60.0 mm.", crankRodJournal: "45.0 mm.", rodRatio: "1.53." }, cylinderHead: { combustionChamberVol: "Direct injection bowl-in-piston design.", intakePortFlow: "24-valve DOHC design. The aluminum casting is excellent, completely eliminating thermal cracking. However, the intake tracts clog rapidly with massive amounts of EGR carbon.", valveSizes: "Intake: 27.2 mm / Exhaust: 27.2 mm.", valveStemDiameter: "6.0 mm.", camshaftDuration: "Mild diesel duration. Driven by the rear-mounted timing chain system.", lifterType: "Hydraulic bucket tappets.", specialFeature: "Sequential Twin-Turbos & 48V Mild Hybrid. The engine features sequential twin-turbos and a 48V mild-hybrid system. This completely eradicates any turbo lag, filling the power gap instantly off idle with electric torque, and making the 3.0L move the massive 8-Series effortlessly." }, oilAndCooling: { oilSquirters: "Yes, dedicated high-pressure under-piston cooling jets.", oilPumpType: "Variable displacement rotor-type pump driven by a dedicated chain.", thermostatOpening: "88°C Mechanical thermostat.", oilCooler: "Features an external water-to-oil heat exchanger." }, fuelSystem: { systemType: "Bosch CP4.2 Common Rail High-Pressure Pump. Universally known for catastrophic internal failure that sends shrapnel through the entire fuel system.", maxPressure: "2700 Bar (Fuel Rail - immensely high pressure).", injectors: "6x Bosch Solenoid Injectors. Incredibly durable, unless fed metal shrapnel from the CP4." }, tuningLimits: { maxSafeTorqueStock: "800+ Nm (The ZF 8HP75 transmission requires an xHP flash to increase clamping force past this point).", maxSafePowerStock: "450 hp (The closed-deck aluminum block handles massive boost safely).", maxSafeRPM: "4800 RPM", weakestLink: "Bosch CP4 Pump (Fatal/Shrapnel), EGR Cooler (Fire Risk), Rear Timing Chain (Snaps/Engine-Out), SCR/AdBlue System, Swirl Flaps, 48V Battery." }, electrical: { coils: "N/A (Compression Ignition).", ecu: "Bosch DDE 8 (Requires FEMTO unlock for tuning)." } },
        recommendedParts: { description: "Crucial maintenance parts to prevent the fatal, catastrophically expensive timing chain and fueling failures of the B57 engine.", parts: [ { category: "CP4 Pump Protection Screen", brand: "Whitbread", note: "CRITICAL: Catches shrapnel if the high-pressure fuel pump fails. Saves the entire fuel system." }, { category: "EGR Cooler (Updated)", brand: "BorgWarner", note: "CRITICAL: The factory cooler leaks coolant and causes engine fires (RECALL ACTIVE)." }, { category: "Timing Chain Kit (Complete)", brand: "Genuine BMW / INA", note: "CRITICAL: Replaces the stretching rear chain and brittle plastic guides. Requires engine-out labor." }, { category: "Vibration Damper", brand: "Corteco", note: "CRITICAL: Replaces the tearing rubber pulley. ONLY use Corteco." }, { category: "High Pressure Fuel Pump (CP4.2)", brand: "Bosch", note: "Proactively replace to prevent catastrophic shrapnel failure." }, { category: "Swirl Flap Blanking Plates", brand: "Aftermarket Billet", note: "CRITICAL: Prevents catastrophic engine ingestion." }, { category: "Intake Manifold Gaskets", brand: "Elring", note: "Required when removing manifold for walnut blasting." }, { category: "Glow Plugs & Relay", brand: "Bosch / Beru", note: "Replace proactively to ensure DPF regeneration." } ] },
