            { interval: "150,000 km", timeLimit: "Unlimited", task: "High-Pressure Fuel Pump (HPFP)", details: "If long cranks or half-engine lights occur under heavy acceleration, the mechanical HPFPs must be replaced.", parts: ["2x Bosch HPFPs"], importance: "High", laborDifficulty: "Advanced", estimatedCost: "1400 EUR" },
            { interval: "100,000 km", timeLimit: "8 years", task: "Valve Cover Gaskets", details: "CRITICAL: Remove the Valvetronic motors, replace the massive rubber gaskets to stop oil leaking onto the hot exhaust manifolds.", parts: ["VCG Sets", "Timing Cover Gaskets"], importance: "High", laborDifficulty: "Advanced", estimatedCost: "550 EUR" },
            { interval: "40,000 km", timeLimit: "4 years", task: "Spark Plug & Coil Replacement", details: "CRITICAL: The S63 burns through spark plugs rapidly. Tuned cars require 1-step colder NGK plugs gapped correctly to prevent misfires under boost.", parts: ["8x NGK Plugs", "8x Eldor Coils"], importance: "High", laborDifficulty: "Intermediate", estimatedCost: "280 EUR" },
            { interval: "150,000 km", timeLimit: "Unlimited", task: "Valvetronic Motor Replacement", details: "If the engine hesitates, throws a drivetrain malfunction, and goes into limp mode, the massive Valvetronic motors are failing.", parts: ["2x VDO Motors", "Gaskets"], importance: "Medium", laborDifficulty: "Intermediate", estimatedCost: "600 EUR" },
            { interval: "150,000 km", timeLimit: "Unlimited", task: "Vibration Damper Inspection", details: "Inspect the incredibly heavy main crankshaft pulley. If the rubber core shows tears, replace it immediately.", parts: ["Corteco Damper"], importance: "High", laborDifficulty: "Advanced", estimatedCost: "300 EUR" }
