        sisterModels: [ { name: "BMW M5 Competition (F90)", note: "The legendary F90 M5 utilized the exact same S63TU4 engine, establishing it as the absolute benchmark for modern super-sedan performance." } ],
        tuningPotential: [
          { stage: "Stage 1 (FEMTO Unlock + Bootmod3 / MHD Flash)", power: "700 - 730 hp", notes: "THE ULTIMATE VALUE UPGRADE. A simple OBD flash (after physical FEMTO bench unlock) safely unlocks massive horsepower and transforms the M8 into a violently fast hypercar. The twin-scroll turbos respond instantly. The S63 M-block handles this easily, but you MUST ensure your HPFPs are healthy and spark plugs are fresh, or it will immediately misfire and limp mode.", zeroToHundred: "2.9s", hundredToTwoHundred: "6.5s" },
          { stage: "Stage 2 (Downpipes, OPF Delete & Tune)", power: "750 - 780 hp", notes: "Requires installing high-flow catless downpipes and physically bypassing the restrictive OPF filters to remove massive heat restriction from the Hot-V twin turbos. This provides a deafening V8 roar. The M-block handles this power effortlessly. You MUST install an xHP transmission flash to increase the clamping force of the ZF 8HP76.", zeroToHundred: "2.7s", hundredToTwoHundred: "6.0s" },
          { stage: "Stage 3 (Upgraded Turbos & Fueling)", power: "850 - 900+ hp", notes: "Requires upgrading the twin turbos to larger hybrid units. The immortal S63 block and forged crank handle 850hp on stock internals effortlessly. However, the High-Pressure Fuel Pumps will struggle to deliver enough fuel, requiring incredibly expensive upgrades, and the ZF automatic transmission will be completely obliterated without a specialized rebuild.", zeroToHundred: "2.5s", hundredToTwoHundred: "5.5s" }
        ],
