        engineeringData: { blockDesign: "90-degree V8, Closed-deck Aluminum Block with wire-arc sprayed cylinder liners. The S63 is a true M-Division engine architecture. It utilizes a highly robust closed-deck design, vastly increasing rigidity. The Competition package includes stiffer engine mounts for more direct power transfer. The 'Hot-V' layout provides instantaneous response, and the thermal management is heavily upgraded for track use.", crankshaft: "Forged Steel, Cross-plane design, supported by 5 massive main bearings. Exceptionally smooth and capable of withstanding unbelievable torque loads.", pistonSpeed: "14.4 m/s @ 6500 RPM.", alternator: "210A Water-Cooled (Liquid Cooled). A highly over-engineered, incredibly expensive unit encased in a coolant jacket.", rotatingAssembly: { pistonConstruction: "Forged aluminum alloy. Features a 10.0:1 compression ratio, engineered specifically by BMW M to handle massive boost.", wristPinDiameter: "22 mm.", connectingRodLength: "144.3 mm.", rodBoltSize: "M10.", crankMainJournal: "70.0 mm.", crankRodJournal: "54.0 mm.", rodRatio: "1.62." }, cylinderHead: { combustionChamberVol: "Direct injection bowl-in-piston design.", intakePortFlow: "32-valve DOHC design. The cylinder heads are 'reverse flow' (intake on the outside, exhaust on the inside). They flow incredible amounts of air.", valveSizes: "Intake: 33.0 mm / Exhaust: 29.0 mm.", valveStemDiameter: "6.0 mm.", camshaftDuration: "Variable on BOTH Intake and Exhaust sides. Controlled dynamically by Dual VANOS and Valvetronic lift.", lifterType: "Hydraulic bucket tappets.", specialFeature: "M-Power Architecture & Cross-Bank Exhaust Manifold. The S63 features a highly complex exhaust manifold that merges pulses from opposite cylinder banks perfectly into the twin-scroll turbos. This creates absolutely devastating, instantaneous throttle response and the signature S63 howl, further amplified by the Competition's sport exhaust." }, oilAndCooling: { oilSquirters: "Yes, dedicated high-pressure under-piston cooling jets.", oilPumpType: "Variable displacement map-controlled pump. Specific high-G-force M-baffling.", thermostatOpening: "105°C Electronically mapped thermostat.", oilCooler: "Features a massive external air-to-oil heat exchanger." }, fuelSystem: { systemType: "High Precision Direct Injection. Operating at 350 Bar.", maxPressure: "350 Bar (Fuel Rail). Driven by TWO highly stressed mechanical HPFPs.", injectors: "8x Bosch Solenoid Injectors. Vastly more reliable than the fatal early Piezo units." }, tuningLimits: { maxSafeTorqueStock: "900+ Nm (The ZF 8HP76 transmission requires an xHP flash to safely manage massive torque increases).", maxSafePowerStock: "800+ hp (The M-Division block and forged internals are incredibly strong).", maxSafeRPM: "7200 RPM", weakestLink: "Coolant Expansion Tank (Explodes), OPF Exhaust Filters (Overheat Turbos), High-Pressure Fuel Pumps, Valve Stem Seals." }, electrical: { coils: "Individual Coil Pack system (8x Coil-on-Plug).", ecu: "Dual Bosch MG1 (Heavily encrypted - Requires physical FEMTO bench unlock)." } },
        recommendedParts: { description: "Crucial maintenance parts to prevent the fatal, catastrophically expensive cooling and fueling failures of the S63 M-V8.", parts: [ { category: "Aluminum Coolant Expansion Tank", brand: "Aftermarket Billet", note: "CRITICAL: Replaces the fatally flawed plastic factory tank." }, { category: "High Pressure Fuel Pumps (HPFP)", brand: "Genuine BMW / Bosch", note: "CRITICAL: Requires 2 units. Replaces the failing mechanical pumps." }, { category: "Valvetronic Motors", brand: "VDO / Continental", note: "Requires 2 units. Replace if the engine enters limp mode." }, { category: "Valve Cover Gasket Set", brand: "Victor Reinz", note: "CRITICAL: Requires 2 massive kits. Cures oil leaking onto the hot exhaust manifolds." }, { category: "Upgraded Ignition Coils & Plugs", brand: "Eldor / NGK 1-Step Colder", note: "Mandatory for curing misfires, especially if running Bootmod3 tunes." }, { category: "Vibration Damper", brand: "Corteco", note: "Replaces the tearing rubber crank pulley before it throws the belt." }, { category: "Water Pump & Thermostat", brand: "Saleri / Wahler", note: "Replace proactively to ensure bulletproof cooling for the massive V8." }, { category: "Viton Valve Stem Seal Kit", brand: "Elring", note: "CRITICAL: Mandatory upgrade if the engine starts smoking blue." } ] },
